{"implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    edge_min = {}
    for u, v, d in distances:
        if u < v:
            a, b = u, v
        else:
            a, b = v, u
        key = (a, b)
        mr = max(core[u], core[v], d)
        if key not in edge_min or mr < edge_min[key]:
            edge_min[key] = mr
    edges = [(w, a, b) for (a,b), w in edge_min.items()]
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Graph is disconnected')
    return {'mst_edges': mst_edges, 'total_weight': total_weight}
"}

